window.M3D.css=".m3root{--bg:#eef0f2;--cd:#fbfbfc;--ln:#d9dcdf;--fg:#22262b;--mu:#69707a;--or:#e8792b;--gr:#2f9e5b;--rd:#c0392b;background:var(--bg);color:var(--fg);font-size:15px;line-height:1.4;direction:rtl;padding:10px 16px 40px;-webkit-user-select:none;user-select:none;text-align:right}.m3root *{box-sizing:border-box}.m3root button{font-family:inherit;margin:0;min-height:0;box-shadow:none}.m3real .demo,.m3tn .demo,.m3tn .notn,.m3tn .rmt{display:none!important}.m3root .phi{display:block;width:100%;max-height:260px;object-fit:cover;border-radius:12px;margin-top:8px;background:#e4e7ea;min-height:80px}\n.m3root .m3w{max-width:560px;margin:0 auto;display:flex;flex-direction:column;gap:10px}.m3root .m3top{display:flex;align-items:center;justify-content:space-between;gap:8px}.m3root .m3dm{background:#fff3e6;border:1px solid var(--or);color:#a8500f;border-radius:999px;padding:3px 12px;font-size:12.5px;font-weight:700}.m3root h1{font-size:18px;margin:0}.m3root .m3seg{display:grid;gap:5px;background:#e4e7ea;border-radius:13px;padding:4px}.m3root .m3seg button{border:0;background:transparent;border-radius:10px;padding:8px 2px;font:inherit;color:var(--mu);cursor:pointer}.m3root .m3seg button.on{background:#fff;color:var(--fg);font-weight:700;box-shadow:0 1px 3px rgba(0,0,0,.12)}.m3root .m3vw{position:relative;border-radius:20px;overflow:hidden;background:linear-gradient(#f7f8f9,#e3e6e9);border:1px solid var(--ln);touch-action:none}.m3root #m3v{display:block;width:100%;height:auto;aspect-ratio:1/1.02;touch-action:none}.m3root #m3tags{position:absolute;inset:0;pointer-events:none}.m3root #m3tags b{position:absolute;transform:translate(-50%,-50%);min-width:22px;height:22px;padding:0 6px;border-radius:11px;background:var(--rd);color:#fff;font-size:12.5px;display:grid;place-items:center;box-shadow:0 2px 6px rgba(0,0,0,.25);pointer-events:auto;cursor:pointer}.m3root #m3tags span{position:absolute;transform:translate(-50%,-50%);font-size:11px;color:#4b525b;background:rgba(255,255,255,.78);padding:1px 7px;border-radius:8px;white-space:nowrap}.m3root .m3hint{position:absolute;bottom:8px;inset-inline:0;text-align:center;font-size:11.5px;color:#7a828c;pointer-events:none}.m3root .m3c{background:var(--cd);border:1px solid var(--ln);border-radius:16px;padding:12px}.m3root .m3c h2{font-size:13px;color:var(--mu);font-weight:600;margin:0 0 8px}.m3root .m3rw{display:grid;grid-template-columns:64px 1fr;align-items:center;gap:8px;margin-top:6px;font-size:13.5px}.m3root .m3sw{display:flex;gap:6px}.m3root .m3sw button{width:34px;height:34px;border-radius:50%;border:2px solid #cfd3d8;cursor:pointer;padding:0}.m3root .m3sw button.on{border-color:var(--fg);box-shadow:0 0 0 2px #fff inset}.m3root input[type=range]{width:100%;accent-color:var(--or)}.m3root .m3it{display:flex;justify-content:space-between;gap:10px;padding:6px 0;border-top:1px solid var(--ln);font-size:14px}.m3root .m3it:first-of-type{border-top:0}.m3root .m3st{flex:none;font-size:12.5px;font-weight:700}.m3root .s2{color:var(--gr)}.m3root .s1{color:#b8620f}.m3root .s0{color:#8b929b}.m3root .s3{color:var(--rd)}.m3root .m3ch{display:flex;flex-wrap:wrap;gap:6px}.m3root .m3ch span{border:1px solid var(--ln);border-radius:999px;padding:4px 10px;font-size:12.5px;background:#fff;display:inline-flex;align-items:center;gap:6px}.m3root .m3ch i{background:var(--c);width:9px;height:9px;border-radius:50%;display:inline-block}.m3root #m3rmc button{color:var(--fg);border:1px solid var(--ln);background:#fff;border-radius:999px;padding:6px 12px;font:inherit;font-size:13px;cursor:pointer}.m3root .m3lg{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:12.5px;color:var(--mu)}.m3root .m3lg i{background:var(--c);display:inline-block;width:11px;height:11px;border-radius:3px;margin-inline-end:5px;vertical-align:-1px}.m3root .m3tg{display:flex;align-items:center;justify-content:space-between;font-size:14px}.m3root .m3tg button{color:var(--fg);border:1px solid var(--ln);background:#fff;border-radius:999px;padding:6px 14px;font:inherit;cursor:pointer}.m3root .m3tg button.on{border-color:var(--or);background:#fff7f0;font-weight:700}.m3root #m3tags b.dd{min-width:0;width:20px;height:20px;padding:0;border:3px solid #fff}.m3root .phx{margin-top:8px;border:1px dashed #c9ced4;border-radius:12px;background:#f1f3f5;color:#69707a;font-size:13px;display:grid;place-items:center;aspect-ratio:16/9}.m3root .sysb{display:flex;flex-wrap:wrap;gap:6px}.m3root .sysb button{color:var(--fg);border:1px solid var(--ln);background:#fff;border-radius:999px;padding:7px 14px;font:inherit;cursor:pointer}.m3root .sysb button.on{border-color:var(--or);background:#fff7f0;font-weight:700}.m3root #m3rmc button.ok{border-color:var(--gr);color:#1f7a44;font-weight:700}.m3root .rmt{flex-basis:100%;font-size:12.5px;color:var(--mu)}.m3root .m3seg.sysb{display:grid}.m3root .m3seg.sysb button{border:0;border-radius:10px;padding:8px 2px;background:transparent;color:var(--mu);font-weight:400}.m3root .m3seg.sysb button.on{background:#fff3e6;color:#a8500f;font-weight:700;box-shadow:0 1px 3px rgba(0,0,0,.12)}.m3root [hidden]{display:none!important}.m3root .zm{position:absolute;top:10px;left:10px;display:flex;flex-direction:column;gap:6px}.m3root .zm button{width:42px;height:42px;border-radius:12px;border:1px solid var(--ln);background:rgba(255,255,255,.93);font-size:24px;font-weight:600;line-height:1;color:var(--fg);cursor:pointer;padding:0}.m3root .here{position:absolute;top:12px;right:10px;background:rgba(255,255,255,.93);border:1px solid var(--ln);border-radius:999px;padding:5px 12px;font-size:13px;font-weight:700}.m3root .m3nav{position:absolute;bottom:30px;left:10px;right:10px;display:grid;grid-template-columns:1fr 1.15fr 1fr;gap:6px}.m3root .m3nav button{border:1px solid var(--ln);background:rgba(255,255,255,.93);border-radius:12px;padding:10px 2px;font:inherit;font-weight:600;color:var(--fg);cursor:pointer}.m3root button:active{transform:scale(.96)}";
